try {
if(typeof TavernHelper==='undefined'||typeof SillyTavern==='undefined')throw Error('需要酒馆助手');
const c=SillyTavern.getContext();
if(!c.getRequestHeaders||!c.saveChat)throw Error('当前酒馆接口不兼容');
window.parent.__arkPlayer?.destroy();
const {mount}=await import("https://epsilonmeow.github.io/arknights-story-player/versions/0.3.7/app.mjs");
await mount({parent:window.parent,helper:TavernHelper,core:()=>SillyTavern.getContext(),eventOn,tavern_events});
} catch(error) {window.parent.toastr?.error('播放器未载入：请检查网络、酒馆助手和版本要求，再重新启用脚本。');console.error('[ArkPlayer] startup failed:',error?.name);}
